using System;
using System.Collections.Generic;
using UnityEngine;

namespace AutoSavePro.PawUI
{
    /// <summary>
    /// Signed-distance / inside-test helpers for glyph shapes. Coordinates are the unit square with y UP
    /// (0,0 = bottom-left), which is how GUI.DrawTexture shows a texture. Use them in PawGlyphs.Define.
    /// </summary>
    internal static class PawShapes
    {
        internal static float Circle(float x, float y, float cx, float cy)
        {
            var dx = x - cx;
            var dy = y - cy;
            return Mathf.Sqrt(dx * dx + dy * dy);
        }

        /// <summary>Distance from (px,py) to the segment a-b. "Seg(...) &lt; w" is a capsule stroke of half-width w.</summary>
        internal static float Seg(float px, float py, float ax, float ay, float bx, float by)
        {
            var pax = px - ax;
            var pay = py - ay;
            var bax = bx - ax;
            var bay = by - ay;
            var h = Mathf.Clamp01((pax * bax + pay * bay) / (bax * bax + bay * bay));
            var dx = pax - bax * h;
            var dy = pay - bay * h;
            return Mathf.Sqrt(dx * dx + dy * dy);
        }

        /// <summary>Signed distance to a rounded box (center, half size, corner radius). &lt; 0 = inside.</summary>
        internal static float RoundBox(float px, float py, float cx, float cy, float hx, float hy, float r)
        {
            var qx = Mathf.Abs(px - cx) - hx + r;
            var qy = Mathf.Abs(py - cy) - hy + r;
            var ox = Mathf.Max(qx, 0f);
            var oy = Mathf.Max(qy, 0f);
            return Mathf.Sqrt(ox * ox + oy * oy) + Mathf.Min(Mathf.Max(qx, qy), 0f) - r;
        }

        internal static bool Ellipse(float x, float y, float cx, float cy, float rx, float ry, float degrees)
        {
            var a = degrees * Mathf.Deg2Rad;
            var dx = x - cx;
            var dy = y - cy;
            var ux = dx * Mathf.Cos(a) + dy * Mathf.Sin(a);
            var uy = -dx * Mathf.Sin(a) + dy * Mathf.Cos(a);
            return (ux / rx) * (ux / rx) + (uy / ry) * (uy / ry) <= 1f;
        }

        /// <summary>Rotates (x,y) around the square's center (for tilted glyphs: rotate the sample point by -angle).</summary>
        internal static void Rotate(ref float x, ref float y, float degrees)
        {
            var a = degrees * Mathf.Deg2Rad;
            var dx = x - 0.5f;
            var dy = y - 0.5f;
            x = 0.5f + dx * Mathf.Cos(a) - dy * Mathf.Sin(a);
            y = 0.5f + dx * Mathf.Sin(a) + dy * Mathf.Cos(a);
        }

        /// <summary>Angle of (x,y) around (cx,cy) in degrees, 0..360, counter-clockwise from +x.</summary>
        internal static float Angle(float x, float y, float cx = 0.5f, float cy = 0.5f)
        {
            var a = Mathf.Atan2(y - cy, x - cx) * Mathf.Rad2Deg;
            return a < 0f ? a + 360f : a;
        }

        internal static bool Ring(float x, float y, float cx, float cy, float radius, float halfWidth) =>
            Mathf.Abs(Circle(x, y, cx, cy) - radius) < halfWidth;

        internal static bool InTriangle(float px, float py, float ax, float ay, float bx, float by, float cx, float cy)
        {
            var d1 = (px - bx) * (ay - by) - (ax - bx) * (py - by);
            var d2 = (px - cx) * (by - cy) - (bx - cx) * (py - cy);
            var d3 = (px - ax) * (cy - ay) - (cx - ax) * (py - ay);
            var neg = d1 < 0 || d2 < 0 || d3 < 0;
            var pos = d1 > 0 || d2 > 0 || d3 > 0;
            return !(neg && pos);
        }

        /// <summary>Even-odd point-in-polygon; pts = x0,y0,x1,y1,...</summary>
        internal static bool InPoly(float px, float py, float[] pts)
        {
            var inside = false;
            var n = pts.Length / 2;
            for (int i = 0, j = n - 1; i < n; j = i++)
            {
                float xi = pts[2 * i], yi = pts[2 * i + 1], xj = pts[2 * j], yj = pts[2 * j + 1];
                if ((yi > py) != (yj > py) && px < (xj - xi) * (py - yi) / (yj - yi) + xi) inside = !inside;
            }
            return inside;
        }

        /// <summary>Four-point sparkle (astroid) of radius r.</summary>
        internal static bool Sparkle(float x, float y, float cx, float cy, float r)
        {
            var dx = Mathf.Abs(x - cx) / r;
            var dy = Mathf.Abs(y - cy) / r;
            return Mathf.Sqrt(dx) + Mathf.Sqrt(dy) <= 1f;
        }

        /// <summary>Five-point star (outer radius R, inner radius r), one tip pointing up.</summary>
        internal static bool Star(float x, float y, float cx, float cy, float outer, float inner)
        {
            const float sector = Mathf.PI * 2f / 5f;
            var a = Mathf.Atan2(y - cy, x - cx);
            var d = Circle(x, y, cx, cy);
            var b = Mathf.Repeat(a - Mathf.PI / 2f, sector);
            if (b > sector / 2f) b = sector - b;
            var px = d * Mathf.Cos(b);
            var py = d * Mathf.Sin(b);
            var bx = inner * Mathf.Cos(sector / 2f);
            var by = inner * Mathf.Sin(sector / 2f);
            return (bx - outer) * py - by * (px - outer) >= 0f;
        }

        internal static bool Paw(float x, float y)
        {
            return Ellipse(x, y, 0.5f, 0.305f, 0.245f, 0.19f, 0f)
                   || Ellipse(x, y, 0.375f, 0.235f, 0.135f, 0.125f, 0f)
                   || Ellipse(x, y, 0.625f, 0.235f, 0.135f, 0.125f, 0f)
                   || Ellipse(x, y, 0.5f, 0.205f, 0.13f, 0.11f, 0f)
                   || Ellipse(x, y, 0.155f, 0.555f, 0.095f, 0.125f, -28f)
                   || Ellipse(x, y, 0.845f, 0.555f, 0.095f, 0.125f, 28f)
                   || Ellipse(x, y, 0.365f, 0.76f, 0.1f, 0.13f, -10f)
                   || Ellipse(x, y, 0.635f, 0.76f, 0.1f, 0.13f, 10f);
        }
    }

    /// <summary>
    /// Procedural glyph library: white alpha masks (4x4 supersampled, mipmapped) rasterized from code - no image
    /// files. Tint them with PawGUI.Glyph(rect, tex, color). Textures are created lazily on first use, cached,
    /// owned by PawTheme (destroyed on release / domain reload) and rebuilt transparently afterwards.
    /// Add your own with <see cref="Define"/> (e.g. in the window's static constructor) using PawShapes.
    /// </summary>
    internal static class PawGlyphs
    {
        internal const int Size = 48;
        internal const int LargeSize = 128;
        internal const float TiltDegrees = -20f;

        private static readonly Dictionary<string, Func<float, float, bool>> Shapes = new Dictionary<string, Func<float, float, bool>>(StringComparer.Ordinal);
        private static readonly Dictionary<string, Texture2D> Small = new Dictionary<string, Texture2D>(StringComparer.Ordinal);
        private static readonly Dictionary<string, Texture2D> Large = new Dictionary<string, Texture2D>(StringComparer.Ordinal);
        private static readonly Dictionary<string, Texture2D> Tilted = new Dictionary<string, Texture2D>(StringComparer.Ordinal);
        private static readonly HashSet<string> Warned = new HashSet<string>(StringComparer.Ordinal);
        private static readonly List<string> IdList = new List<string>();

        /// <summary>Every built-in glyph id, in gallery order.</summary>
        internal static readonly string[] BuiltinIds =
        {
            "paw", "check", "cross", "plus", "dash", "info", "letter-i", "question", "warn", "sparkle", "star", "heart",
            "search", "filter", "list", "grid", "layers", "folder", "box", "cube", "image", "palette", "material", "tag", "link",
            "external", "upload", "download", "save", "copy", "trash", "pencil", "wand", "gear", "refresh", "clock", "bell", "dice",
            "play", "pause", "stop", "lock", "unlock", "shield", "key", "eye", "bolt", "home", "sun", "moon",
            "cloud", "bug", "chevron", "chevron-down", "arrow-right",
        };

        static PawGlyphs()
        {
            RegisterBuiltins();
        }

        /// <summary>All registered ids (built-in first, then custom ones in definition order). Do not modify.</summary>
        internal static IReadOnlyList<string> Ids => IdList;

        internal static bool Has(string id) => id != null && Shapes.ContainsKey(id);

        /// <summary>The raw inside-test for a glyph (null when unknown) - e.g. to rasterize it in two colors.</summary>
        internal static Func<float, float, bool> Shape(string id) => id != null && Shapes.TryGetValue(id, out var s) ? s : null;

        /// <summary>
        /// Adds (or replaces) a glyph. <paramref name="inside"/> gets unit-square coordinates, y up, and returns
        /// whether the point is inside the shape. Keep strokes >= 0.05 half-width so they survive at 14px.
        /// </summary>
        internal static void Define(string id, Func<float, float, bool> inside)
        {
            if (string.IsNullOrEmpty(id) || inside == null) return;
            if (!Shapes.ContainsKey(id)) IdList.Add(id);
            Shapes[id] = inside;
            Forget(Small, id);
            Forget(Large, id);
            Forget(Tilted, id);
        }

        /// <summary>48px mask - icons, buttons, tiles.</summary>
        internal static Texture2D Get(string id) => Build(Small, id, Size, 0f);

        /// <summary>128px mask - logo tile, big empty states, watermark-size art.</summary>
        internal static Texture2D GetLarge(string id) => Build(Large, id, LargeSize, 0f);

        /// <summary>128px mask rotated by TiltDegrees - the hero watermark.</summary>
        internal static Texture2D GetTilted(string id) => Build(Tilted, id, LargeSize, TiltDegrees);

        // ---- Typed shortcuts (no allocation; dictionary lookups) ---------------------------------------
        internal static Texture2D PawGlyph => Get("paw");
        internal static Texture2D Check => Get("check");
        internal static Texture2D Cross => Get("cross");
        internal static Texture2D Plus => Get("plus");
        internal static Texture2D Dash => Get("dash");
        internal static Texture2D Info => Get("info");
        internal static Texture2D LetterI => Get("letter-i");
        internal static Texture2D Question => Get("question");
        internal static Texture2D Warn => Get("warn");
        internal static Texture2D SparkleGlyph => Get("sparkle");
        internal static Texture2D StarGlyph => Get("star");
        internal static Texture2D Heart => Get("heart");
        internal static Texture2D Search => Get("search");
        internal static Texture2D Filter => Get("filter");
        internal static Texture2D List => Get("list");
        internal static Texture2D Grid => Get("grid");
        internal static Texture2D Layers => Get("layers");
        internal static Texture2D Folder => Get("folder");
        internal static Texture2D Box => Get("box");
        internal static Texture2D Cube => Get("cube");
        internal static Texture2D Image => Get("image");
        internal static Texture2D Palette => Get("palette");
        internal static Texture2D Material => Get("material");
        internal static Texture2D Tag => Get("tag");
        internal static Texture2D Link => Get("link");
        internal static Texture2D External => Get("external");
        internal static Texture2D Upload => Get("upload");
        internal static Texture2D Download => Get("download");
        internal static Texture2D Save => Get("save");
        internal static Texture2D Copy => Get("copy");
        internal static Texture2D Trash => Get("trash");
