        internal static Texture2D Cloud => Get("cloud");
        internal static Texture2D Bug => Get("bug");
        internal static Texture2D Chevron => Get("chevron");
        internal static Texture2D ChevronDown => Get("chevron-down");
        internal static Texture2D ArrowRight => Get("arrow-right");

        /// <summary>Called by PawTheme when it destroys its textures.</summary>
        internal static void ClearCache()
        {
            Small.Clear();
            Large.Clear();
            Tilted.Clear();
        }

        private static void Forget(Dictionary<string, Texture2D> cache, string id)
        {
            if (cache.TryGetValue(id, out var tex) && tex != null) UnityEngine.Object.DestroyImmediate(tex);
            cache.Remove(id);
        }

        private static Texture2D Build(Dictionary<string, Texture2D> cache, string id, int size, float degrees)
        {
            if (id == null) return null;
            if (cache.TryGetValue(id, out var tex) && tex != null) return tex;
            if (!Shapes.TryGetValue(id, out var shape))
            {
                if (Warned.Add(id)) Debug.LogWarning("PawUI: unknown glyph id '" + id + "' - showing 'question'. Known: PawGlyphs.BuiltinIds or PawGlyphs.Define.");
                if (id == "question") return null;
                return Build(cache, "question", size, degrees);
            }
            if (Mathf.Abs(degrees) > 0.01f)
            {
                var inner = shape;
                // Rotating the sample point by -20 degrees tilts the drawn glyph the way PawEncrypt's watermark leans.
                shape = (x, y) =>
                {
                    PawShapes.Rotate(ref x, ref y, degrees);
                    return inner(x, y);
                };
            }
            tex = Rasterize(size, shape, "PawUI Glyph " + id);
            cache[id] = tex;
            return tex;
        }

        /// <summary>White mask with 4x4 supersampled coverage in alpha; mipmapped so it stays smooth when drawn small.</summary>
        internal static Texture2D Rasterize(int size, Func<float, float, bool> inside, string name)
        {
            const int ss = 4;
            var tex = new Texture2D(size, size, TextureFormat.RGBA32, true)
            {
                hideFlags = HideFlags.HideAndDontSave,
                wrapMode = TextureWrapMode.Clamp,
                filterMode = FilterMode.Trilinear,
                name = name,
            };
            var px = new Color32[size * size];
            for (var y = 0; y < size; y++)
            {
                for (var x = 0; x < size; x++)
                {
                    var hits = 0;
                    for (var sy = 0; sy < ss; sy++)
                    {
                        for (var sx = 0; sx < ss; sx++)
                        {
                            var u = (x + (sx + 0.5f) / ss) / size;
                            var v = (y + (sy + 0.5f) / ss) / size;
                            if (inside(u, v)) hits++;
                        }
                    }
                    px[y * size + x] = new Color32(255, 255, 255, (byte)(255 * hits / (ss * ss)));
                }
            }
            tex.SetPixels32(px);
            tex.Apply(true, true);
            PawTheme.Own(tex);
            return tex;
        }

        // ---------------------------------------------------------------------------------------------
        private static void Add(string id, Func<float, float, bool> inside)
        {
            if (!Shapes.ContainsKey(id)) IdList.Add(id);
            Shapes[id] = inside;
        }

        private static readonly float[] BoltPoly = { 0.6f, 0.95f, 0.2f, 0.42f, 0.47f, 0.42f, 0.4f, 0.05f, 0.8f, 0.58f, 0.53f, 0.58f };
        private static readonly float[] FilterPoly = { 0.12f, 0.86f, 0.88f, 0.86f, 0.58f, 0.48f, 0.58f, 0.14f, 0.42f, 0.24f, 0.42f, 0.48f };
        private static readonly float[] TagPoly = { 0.34f, 0.08f, 0.66f, 0.08f, 0.66f, 0.66f, 0.5f, 0.9f, 0.34f, 0.66f };
        private static readonly float[] CubePts = { 0.5f, 0.92f, 0.87f, 0.71f, 0.87f, 0.29f, 0.5f, 0.08f, 0.13f, 0.29f, 0.13f, 0.71f };

        private static bool Tray(float x, float y) =>
            PawShapes.Seg(x, y, 0.16f, 0.14f, 0.84f, 0.14f) < 0.065f || PawShapes.Seg(x, y, 0.16f, 0.14f, 0.16f, 0.36f) < 0.065f ||
            PawShapes.Seg(x, y, 0.84f, 0.14f, 0.84f, 0.36f) < 0.065f;

        private static bool LockBody(float x, float y)
        {
            if (PawShapes.RoundBox(x, y, 0.5f, 0.33f, 0.31f, 0.24f, 0.07f) >= 0f) return false;
            return !(PawShapes.Circle(x, y, 0.5f, 0.37f) < 0.065f || PawShapes.Seg(x, y, 0.5f, 0.37f, 0.5f, 0.22f) < 0.035f);
        }

        private static void RegisterBuiltins()
        {
            Add("paw", PawShapes.Paw);
            Add("check", (x, y) =>
                PawShapes.Seg(x, y, 0.2f, 0.5f, 0.42f, 0.28f) < 0.085f || PawShapes.Seg(x, y, 0.42f, 0.28f, 0.81f, 0.7f) < 0.085f);
            Add("cross", (x, y) =>
                PawShapes.Seg(x, y, 0.26f, 0.26f, 0.74f, 0.74f) < 0.08f || PawShapes.Seg(x, y, 0.26f, 0.74f, 0.74f, 0.26f) < 0.08f);
            Add("plus", (x, y) =>
                PawShapes.Seg(x, y, 0.5f, 0.2f, 0.5f, 0.8f) < 0.08f || PawShapes.Seg(x, y, 0.2f, 0.5f, 0.8f, 0.5f) < 0.08f);
            Add("dash", (x, y) => PawShapes.Seg(x, y, 0.27f, 0.5f, 0.73f, 0.5f) < 0.085f);
            Add("info", (x, y) =>
            {
                var d = PawShapes.Circle(x, y, 0.5f, 0.5f);
                if (d < 0.46f && d > 0.37f) return true;
                return PawShapes.Circle(x, y, 0.5f, 0.69f) < 0.06f || PawShapes.Seg(x, y, 0.5f, 0.28f, 0.5f, 0.52f) < 0.05f;
            });
            Add("letter-i", (x, y) =>
                PawShapes.Circle(x, y, 0.5f, 0.76f) < 0.095f || PawShapes.Seg(x, y, 0.5f, 0.2f, 0.5f, 0.54f) < 0.08f);
            Add("question", (x, y) =>
            {
                var d = PawShapes.Circle(x, y, 0.5f, 0.5f);
                if (d < 0.46f && d > 0.37f) return true;
                var a = PawShapes.Angle(x, y, 0.5f, 0.6f);
                if (Mathf.Abs(PawShapes.Circle(x, y, 0.5f, 0.6f) - 0.12f) < 0.05f && !(a > 200f && a < 290f)) return true;
                return PawShapes.Seg(x, y, 0.5f, 0.48f, 0.5f, 0.42f) < 0.05f || PawShapes.Circle(x, y, 0.5f, 0.27f) < 0.055f;
            });
            Add("warn", (x, y) =>
            {
                if (!PawShapes.InTriangle(x, y, 0.5f, 0.93f, 0.04f, 0.1f, 0.96f, 0.1f)) return false;
                if (PawShapes.Seg(x, y, 0.5f, 0.42f, 0.5f, 0.67f) < 0.06f) return false;
                return PawShapes.Circle(x, y, 0.5f, 0.25f) >= 0.065f;
            });
            Add("sparkle", (x, y) => PawShapes.Sparkle(x, y, 0.5f, 0.5f, 0.48f));
            Add("star", (x, y) => PawShapes.Star(x, y, 0.5f, 0.47f, 0.46f, 0.2f));
            Add("heart", (x, y) =>
            {
                var u = (x - 0.5f) / 0.43f;
                var v = (y - 0.47f) / 0.43f;
                var k = u * u + v * v - 1f;
                return k * k * k - u * u * v * v * v <= 0f;
            });
            Add("search", (x, y) =>
            {
                var d = PawShapes.Circle(x, y, 0.43f, 0.57f);
                return (d < 0.29f && d > 0.2f) || PawShapes.Seg(x, y, 0.63f, 0.37f, 0.84f, 0.16f) < 0.07f;
            });
            Add("filter", (x, y) => PawShapes.InPoly(x, y, FilterPoly));
            Add("list", (x, y) =>
            {
                for (var i = 0; i < 3; i++)
                {
                    var cy = 0.75f - i * 0.25f;
                    if (PawShapes.Circle(x, y, 0.17f, cy) < 0.075f || PawShapes.Seg(x, y, 0.36f, cy, 0.86f, cy) < 0.06f) return true;
                }
                return false;
            });
            Add("grid", (x, y) =>
                PawShapes.RoundBox(x, y, 0.3f, 0.3f, 0.15f, 0.15f, 0.05f) < 0f || PawShapes.RoundBox(x, y, 0.7f, 0.3f, 0.15f, 0.15f, 0.05f) < 0f ||
                PawShapes.RoundBox(x, y, 0.3f, 0.7f, 0.15f, 0.15f, 0.05f) < 0f || PawShapes.RoundBox(x, y, 0.7f, 0.7f, 0.15f, 0.15f, 0.05f) < 0f);
            Add("layers", (x, y) =>
            {
                if (Mathf.Abs(x - 0.5f) / 0.4f + Mathf.Abs(y - 0.64f) / 0.2f <= 1f) return true;
                for (var i = 0; i < 2; i++)
                {
                    var c = i == 0 ? 0.46f : 0.3f;
                    var dist = Mathf.Abs(x - 0.5f) / 0.4f + Mathf.Abs(y - c) / 0.2f;
                    if (Mathf.Abs(dist - 1f) < 0.2f && y < c - 0.02f && Mathf.Abs(x - 0.5f) < 0.4f) return true;
                }
                return false;
            });
            Add("folder", (x, y) =>
                PawShapes.RoundBox(x, y, 0.5f, 0.44f, 0.42f, 0.29f, 0.08f) < 0f || PawShapes.RoundBox(x, y, 0.28f, 0.72f, 0.2f, 0.1f, 0.06f) < 0f);
            Add("box", (x, y) =>
            {
                if (PawShapes.RoundBox(x, y, 0.5f, 0.74f, 0.42f, 0.1f, 0.04f) < 0f) return true;
                if (PawShapes.RoundBox(x, y, 0.5f, 0.35f, 0.36f, 0.25f, 0.05f) >= 0f) return false;
                return PawShapes.RoundBox(x, y, 0.5f, 0.47f, 0.11f, 0.04f, 0.035f) >= 0f;
            });
            Add("cube", (x, y) =>
            {
                const float w = 0.058f;
                for (var i = 0; i < 6; i++)
                {
                    var j = (i + 1) % 6;
                    if (PawShapes.Seg(x, y, CubePts[2 * i], CubePts[2 * i + 1], CubePts[2 * j], CubePts[2 * j + 1]) < w) return true;
                }
                for (var i = 1; i < 6; i += 2)
                {
                    if (PawShapes.Seg(x, y, 0.5f, 0.5f, CubePts[2 * i], CubePts[2 * i + 1]) < w) return true;
                }
                return false;
            });
            Add("image", (x, y) =>
            {
                var frame = PawShapes.RoundBox(x, y, 0.5f, 0.5f, 0.42f, 0.36f, 0.09f);
                if (frame >= 0f) return false;
                if (frame > -0.07f) return true;
                return PawShapes.InTriangle(x, y, 0.16f, 0.2f, 0.42f, 0.56f, 0.68f, 0.2f) ||
                       PawShapes.InTriangle(x, y, 0.46f, 0.2f, 0.64f, 0.42f, 0.84f, 0.2f) || PawShapes.Circle(x, y, 0.68f, 0.64f) < 0.075f;
            });
            // Paint palette: a round board with a thumb notch and four paint wells.
            Add("palette", (x, y) =>
            {
                if (PawShapes.Circle(x, y, 0.5f, 0.5f) > 0.45f) return false;
                if (PawShapes.Circle(x, y, 0.76f, 0.24f) < 0.17f) return false;
                if (PawShapes.Circle(x, y, 0.62f, 0.37f) < 0.07f) return false;
                return !(PawShapes.Circle(x, y, 0.27f, 0.47f) < 0.075f || PawShapes.Circle(x, y, 0.35f, 0.71f) < 0.075f ||
                         PawShapes.Circle(x, y, 0.59f, 0.76f) < 0.075f || PawShapes.Circle(x, y, 0.75f, 0.6f) < 0.075f);
            });
            // Material preview ball: a sphere with a specular highlight and a shading terminator cut out.
            Add("material", (x, y) =>
            {
                if (PawShapes.Circle(x, y, 0.5f, 0.5f) > 0.44f) return false;
                if (PawShapes.Circle(x, y, 0.36f, 0.64f) < 0.095f) return false;
                var t = PawShapes.Circle(x, y, 0.27f, 0.73f);
                return t <= 0.55f || t >= 0.63f;
            });
            Add("tag", (x, y) =>
            {
                PawShapes.Rotate(ref x, ref y, 45f);
                if (PawShapes.Circle(x, y, 0.5f, 0.64f) < 0.065f) return false;
                return PawShapes.InPoly(x, y, TagPoly) || PawShapes.RoundBox(x, y, 0.5f, 0.38f, 0.16f, 0.3f, 0.06f) < 0f;
            });
            Add("link", (x, y) =>
            {
                PawShapes.Rotate(ref x, ref y, -45f);
                return Mathf.Abs(PawShapes.Seg(x, y, 0.5f, 0.2f, 0.5f, 0.42f) - 0.13f) < 0.055f ||
                       Mathf.Abs(PawShapes.Seg(x, y, 0.5f, 0.58f, 0.5f, 0.8f) - 0.13f) < 0.055f ||
                       PawShapes.Seg(x, y, 0.5f, 0.38f, 0.5f, 0.62f) < 0.055f;
            });
            // Opens outside the window: a frame open at its top-right corner with an arrow leaving through the gap.
            Add("external", (x, y) =>
            {
                var box = PawShapes.RoundBox(x, y, 0.44f, 0.44f, 0.32f, 0.32f, 0.09f);
                if (box < 0f && box > -0.075f && !(x > 0.47f && y > 0.47f)) return true;
                return PawShapes.Seg(x, y, 0.45f, 0.45f, 0.84f, 0.84f) < 0.065f || PawShapes.Seg(x, y, 0.58f, 0.86f, 0.86f, 0.86f) < 0.065f ||
                       PawShapes.Seg(x, y, 0.86f, 0.58f, 0.86f, 0.86f) < 0.065f;
            });
            Add("upload", (x, y) =>
                PawShapes.Seg(x, y, 0.5f, 0.36f, 0.5f, 0.84f) < 0.065f || PawShapes.Seg(x, y, 0.5f, 0.86f, 0.3f, 0.66f) < 0.065f ||
                PawShapes.Seg(x, y, 0.5f, 0.86f, 0.7f, 0.66f) < 0.065f || Tray(x, y));
            Add("download", (x, y) =>
                PawShapes.Seg(x, y, 0.5f, 0.86f, 0.5f, 0.38f) < 0.065f || PawShapes.Seg(x, y, 0.5f, 0.36f, 0.3f, 0.56f) < 0.065f ||
                PawShapes.Seg(x, y, 0.5f, 0.36f, 0.7f, 0.56f) < 0.065f || Tray(x, y));
            Add("save", (x, y) =>
            {
                if (PawShapes.RoundBox(x, y, 0.5f, 0.5f, 0.38f, 0.38f, 0.07f) >= 0f) return false;
                if (PawShapes.InTriangle(x, y, 0.72f, 0.9f, 0.9f, 0.9f, 0.9f, 0.72f)) return false;
                if (PawShapes.RoundBox(x, y, 0.47f, 0.73f, 0.17f, 0.1f, 0.03f) < 0f) return false;
                return PawShapes.Circle(x, y, 0.5f, 0.36f) >= 0.1f;
            });
            Add("copy", (x, y) =>
            {
                var front = PawShapes.RoundBox(x, y, 0.6f, 0.4f, 0.26f, 0.26f, 0.07f);
                if (front < 0f) return front > -0.075f;
                var back = PawShapes.RoundBox(x, y, 0.4f, 0.6f, 0.26f, 0.26f, 0.07f);
                return back < 0f && back > -0.075f && front > 0.07f;
            });
            Add("trash", (x, y) =>
            {
                if (PawShapes.RoundBox(x, y, 0.5f, 0.75f, 0.35f, 0.045f, 0.03f) < 0f) return true;
                if (PawShapes.RoundBox(x, y, 0.5f, 0.83f, 0.11f, 0.06f, 0.03f) < 0f) return true;
                if (PawShapes.RoundBox(x, y, 0.5f, 0.38f, 0.26f, 0.3f, 0.07f) >= 0f) return false;
                return !(PawShapes.RoundBox(x, y, 0.41f, 0.38f, 0.03f, 0.17f, 0.02f) < 0f || PawShapes.RoundBox(x, y, 0.59f, 0.38f, 0.03f, 0.17f, 0.02f) < 0f);
            });
            Add("pencil", (x, y) =>
            {
                PawShapes.Rotate(ref x, ref y, 45f);
                if (PawShapes.InTriangle(x, y, 0.38f, 0.28f, 0.62f, 0.28f, 0.5f, 0.06f)) return true;
                if (PawShapes.RoundBox(x, y, 0.5f, 0.56f, 0.12f, 0.28f, 0.02f) >= 0f) return false;
                return PawShapes.RoundBox(x, y, 0.5f, 0.8f, 0.12f, 0.012f, 0f) >= 0f;
            });
            Add("wand", (x, y) =>
                PawShapes.Seg(x, y, 0.16f, 0.16f, 0.6f, 0.6f) < 0.06f || PawShapes.Sparkle(x, y, 0.74f, 0.74f, 0.2f) ||
                PawShapes.Sparkle(x, y, 0.36f, 0.84f, 0.1f) || PawShapes.Sparkle(x, y, 0.86f, 0.4f, 0.09f));
            Add("gear", (x, y) =>
            {
                var d = PawShapes.Circle(x, y, 0.5f, 0.5f);
                if (d <= 0.135f) return false;
                var a = PawShapes.Angle(x, y) * Mathf.Deg2Rad;
                var t = Mathf.Clamp01((Mathf.Cos(a * 8f) - 0.05f) * 2.2f);
                return d < 0.33f + 0.12f * t;
            });
            Add("refresh", (x, y) =>
            {
                const float r0 = 0.3f;
                var a = PawShapes.Angle(x, y);
                if (Mathf.Abs(PawShapes.Circle(x, y, 0.5f, 0.5f) - r0) < 0.068f && !(a > 18f && a < 78f)) return true;
                // Arrowhead at the top end of the arc, pointing clockwise.
                var e = 78f * Mathf.Deg2Rad;
                float px = 0.5f + r0 * Mathf.Cos(e), py = 0.5f + r0 * Mathf.Sin(e);
                float tx = Mathf.Sin(e), ty = -Mathf.Cos(e), nx = Mathf.Cos(e), ny = Mathf.Sin(e);
                return PawShapes.InTriangle(x, y, px + tx * 0.2f, py + ty * 0.2f,
                    px + nx * 0.16f - tx * 0.02f, py + ny * 0.16f - ty * 0.02f, px - nx * 0.16f - tx * 0.02f, py - ny * 0.16f - ty * 0.02f);
            });
            Add("clock", (x, y) =>
            {
                var d = PawShapes.Circle(x, y, 0.5f, 0.5f);
                if (d < 0.45f && d > 0.36f) return true;
                return PawShapes.Seg(x, y, 0.5f, 0.5f, 0.5f, 0.74f) < 0.055f || PawShapes.Seg(x, y, 0.5f, 0.5f, 0.67f, 0.4f) < 0.055f;
            });
            Add("bell", (x, y) =>
                (PawShapes.Ellipse(x, y, 0.5f, 0.42f, 0.28f, 0.4f, 0f) && y > 0.3f) || PawShapes.RoundBox(x, y, 0.5f, 0.3f, 0.38f, 0.055f, 0.05f) < 0f ||
                (PawShapes.Circle(x, y, 0.5f, 0.16f) < 0.085f && y < 0.2f) || PawShapes.Circle(x, y, 0.5f, 0.84f) < 0.06f);
            Add("dice", (x, y) =>
            {
                if (PawShapes.RoundBox(x, y, 0.5f, 0.5f, 0.42f, 0.42f, 0.13f) >= 0f) return false;
                return !(PawShapes.Circle(x, y, 0.3f, 0.7f) < 0.095f || PawShapes.Circle(x, y, 0.5f, 0.5f) < 0.095f || PawShapes.Circle(x, y, 0.7f, 0.3f) < 0.095f);
            });
            Add("play", (x, y) => PawShapes.InTriangle(x, y, 0.3f, 0.16f, 0.3f, 0.84f, 0.86f, 0.5f));
            Add("pause", (x, y) =>
                PawShapes.RoundBox(x, y, 0.33f, 0.5f, 0.1f, 0.32f, 0.05f) < 0f || PawShapes.RoundBox(x, y, 0.67f, 0.5f, 0.1f, 0.32f, 0.05f) < 0f);
            Add("stop", (x, y) => PawShapes.RoundBox(x, y, 0.5f, 0.5f, 0.3f, 0.3f, 0.07f) < 0f);
            Add("lock", (x, y) =>
                LockBody(x, y) || (PawShapes.Ring(x, y, 0.5f, 0.6f, 0.17f, 0.06f) && y > 0.6f) ||
                PawShapes.Seg(x, y, 0.33f, 0.6f, 0.33f, 0.5f) < 0.06f || PawShapes.Seg(x, y, 0.67f, 0.6f, 0.67f, 0.5f) < 0.06f);
            Add("unlock", (x, y) =>
                LockBody(x, y) || (PawShapes.Ring(x, y, 0.5f, 0.66f, 0.17f, 0.06f) && y > 0.66f) || PawShapes.Seg(x, y, 0.33f, 0.66f, 0.33f, 0.5f) < 0.06f);
            Add("shield", (x, y) =>
            {
                if (y > 0.9f || y < 0.08f) return false;
                var w = y > 0.55f ? 0.37f : 0.37f * Mathf.Sqrt(Mathf.Clamp01((y - 0.08f) / 0.47f));
                if (Mathf.Abs(x - 0.5f) > w) return false;
                return !(PawShapes.Seg(x, y, 0.32f, 0.52f, 0.45f, 0.39f) < 0.05f || PawShapes.Seg(x, y, 0.45f, 0.39f, 0.7f, 0.66f) < 0.05f);
            });
            Add("key", (x, y) =>
            {
                PawShapes.Rotate(ref x, ref y, 45f);
                return PawShapes.Ring(x, y, 0.5f, 0.72f, 0.15f, 0.065f) || PawShapes.Seg(x, y, 0.5f, 0.57f, 0.5f, 0.08f) < 0.06f ||
                       PawShapes.Seg(x, y, 0.5f, 0.14f, 0.66f, 0.14f) < 0.055f || PawShapes.Seg(x, y, 0.5f, 0.28f, 0.62f, 0.28f) < 0.055f;
            });
            Add("eye", (x, y) =>
            {
                if (PawShapes.Circle(x, y, 0.5f, 0.5f) < 0.15f) return true;
                var lens = PawShapes.Circle(x, y, 0.5f, 0.06f) < 0.6f && PawShapes.Circle(x, y, 0.5f, 0.94f) < 0.6f;
                var inner = PawShapes.Circle(x, y, 0.5f, 0.06f) < 0.51f && PawShapes.Circle(x, y, 0.5f, 0.94f) < 0.51f;
                return lens && !inner;
            });
            Add("bolt", (x, y) => PawShapes.InPoly(x, y, BoltPoly));
            Add("home", (x, y) =>
            {
                if (PawShapes.Seg(x, y, 0.1f, 0.5f, 0.5f, 0.88f) < 0.065f || PawShapes.Seg(x, y, 0.5f, 0.88f, 0.9f, 0.5f) < 0.065f) return true;
                if (y >= 0.56f || PawShapes.RoundBox(x, y, 0.5f, 0.31f, 0.27f, 0.22f, 0.05f) >= 0f) return false;
                return PawShapes.RoundBox(x, y, 0.5f, 0.2f, 0.075f, 0.12f, 0.03f) >= 0f;
            });
            Add("sun", (x, y) =>
            {
                if (PawShapes.Circle(x, y, 0.5f, 0.5f) < 0.18f) return true;
                for (var k = 0; k < 8; k++)
                {
                    var a = k * 45f * Mathf.Deg2Rad;
                    float c = Mathf.Cos(a), s = Mathf.Sin(a);
                    if (PawShapes.Seg(x, y, 0.5f + 0.29f * c, 0.5f + 0.29f * s, 0.5f + 0.41f * c, 0.5f + 0.41f * s) < 0.055f) return true;
                }
                return false;
            });
            Add("moon", (x, y) => PawShapes.Circle(x, y, 0.47f, 0.5f) < 0.38f && PawShapes.Circle(x, y, 0.66f, 0.62f) > 0.3f);
            Add("cloud", (x, y) =>
                PawShapes.Circle(x, y, 0.36f, 0.44f) < 0.19f || PawShapes.Circle(x, y, 0.58f, 0.54f) < 0.24f ||
                PawShapes.Circle(x, y, 0.76f, 0.4f) < 0.16f || PawShapes.RoundBox(x, y, 0.53f, 0.33f, 0.33f, 0.1f, 0.1f) < 0f);
            Add("bug", (x, y) =>
            {
                var body = PawShapes.Ellipse(x, y, 0.5f, 0.42f, 0.22f, 0.3f, 0f);
                var head = PawShapes.Circle(x, y, 0.5f, 0.78f) < 0.13f;
                if (body || head) return !(Mathf.Abs(x - 0.5f) < 0.025f && y < 0.66f);
                for (var i = 0; i < 3; i++)
                {
                    var ly = 0.52f - i * 0.12f;
                    var dy = 0.08f - i * 0.08f;
                    if (PawShapes.Seg(x, y, 0.5f, ly, 0.12f, ly + dy) < 0.045f || PawShapes.Seg(x, y, 0.5f, ly, 0.88f, ly + dy) < 0.045f) return true;
                }
                return false;
            });
            Add("chevron", (x, y) =>
                PawShapes.Seg(x, y, 0.38f, 0.2f, 0.64f, 0.5f) < 0.075f || PawShapes.Seg(x, y, 0.64f, 0.5f, 0.38f, 0.8f) < 0.075f);
            Add("chevron-down", (x, y) =>
                PawShapes.Seg(x, y, 0.2f, 0.62f, 0.5f, 0.36f) < 0.075f || PawShapes.Seg(x, y, 0.5f, 0.36f, 0.8f, 0.62f) < 0.075f);
            Add("arrow-right", (x, y) =>
                PawShapes.Seg(x, y, 0.16f, 0.5f, 0.8f, 0.5f) < 0.07f || PawShapes.Seg(x, y, 0.82f, 0.5f, 0.58f, 0.74f) < 0.07f ||
                PawShapes.Seg(x, y, 0.82f, 0.5f, 0.58f, 0.26f) < 0.07f);

            // Keep IdList in gallery order (BuiltinIds), then anything else.
            IdList.Clear();
            foreach (var id in BuiltinIds)
            {
                if (Shapes.ContainsKey(id)) IdList.Add(id);
            }
            foreach (var id in Shapes.Keys)
            {
                if (!IdList.Contains(id)) IdList.Add(id);
            }
        }
    }
}
